  ["open_items", "\"$HORIZON_BIN\" inbox list --mine --status open --comments 0 --json | jq '{items:[.items[]|select(.kind!=\"protection\")|{id,kind,title:(.body|split(\"\\n\")[0]),author,audience,owner_task,updated_at,started_by:.metadata.started_by}], warnings}'"],
